//! Raw FFI bindings to the llama.cpp fork that implements Nemotron Dory.
//!
//! Generated by `bindgen` from the fork's `include/llama.h` at build time.
#![allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code,
    clippy::all
)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));

/// The fork commit this crate was built against (stamped by `build.rs`).
pub const FORK_COMMIT: &str = env!("DORY_FORK_COMMIT");

#[cfg(test)]
mod tests {
    use super::*;
    use std::mem::{offset_of, size_of};

    /// `llama_model_kv_override` is `{ int tag; char key[128]; union { i64; f64; bool; char[128] } }`.
    /// On LP64 that is 4 + 128 bytes, padded to 8 for the union, then 128 bytes of union storage.
    #[test]
    fn kv_override_layout_matches_header() {
        assert_eq!(size_of::<llama_model_kv_override>(), 264);
        assert_eq!(offset_of!(llama_model_kv_override, key), 4);
    }

    #[test]
    fn kv_override_tags_match_header_enum() {
        assert_eq!(llama_model_kv_override_type_LLAMA_KV_OVERRIDE_TYPE_INT, 0);
        assert_eq!(llama_model_kv_override_type_LLAMA_KV_OVERRIDE_TYPE_STR, 3);
    }

    #[test]
    fn default_params_match_header_intent() {
        let mp = unsafe { llama_model_default_params() };
        // -1 means "offload every layer", which the harness relies on.
        assert_eq!(mp.n_gpu_layers, -1);
        let cp = unsafe { llama_context_default_params() };
        assert_eq!(cp.n_batch, 2048);
        assert_eq!(cp.n_ubatch, 512);
    }

    #[test]
    fn fork_commit_is_stamped() {
        assert!(!FORK_COMMIT.is_empty());
    }
}
